 resource.setrlimit(resource.RLIMIT_CORE,(0,0))
 p=argparse.ArgumentParser();p.add_argument('--kcc',type=Path,required=True);p.add_argument('--sanitize-c',action='store_true');p.add_argument('--report',type=Path,required=True);a=p.parse_args();binary=a.kcc.resolve();records=[]
 env={**os.environ,'PATH':'/no-host-tools','XDG_CACHE_HOME':'/var/tmp/Awl-vectors-cache','ASAN_OPTIONS':'detect_leaks=1:abort_on_error=1'}
 with tempfile.TemporaryDirectory(prefix='Awl-vectors-tests-',dir='/var/tmp') as td:
  work=Path(td)
  def build(label,body='',source=None,error=None,files=None):
   folder=work/str(len(records));folder.mkdir(exist_ok=True);src=folder/'main.aw';src.write_text(source if source is not None else 'func main()->i64 '+body+' return 0; end;')
   for name,text in (files or {}).items():(folder/name).write_text(text)
   exe=folder/'app';command='check' if error else 'emit-c' if a.sanitize_c else 'build'
